// Some portions generated by Codex
package org.eclipse.rdf4j.common.iteration;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.NoSuchElementException;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

@Execution(ExecutionMode.SAME_THREAD)
@Timeout(value = 20, unit = TimeUnit.SECONDS)
class ManualTimeoutTimerLeaseTest {

	@Test
	void manualTimeoutReleasesTimerWithoutExplicitWrapperClose() throws Exception {
		CountDownLatch sourceClosed = new CountDownLatch(1);
		AtomicInteger closeCalls = new AtomicInteger();
		CloseableIteration<String> source = new CloseableIteration<>() {
			@Override
			public boolean hasNext() {
				return true;
			}

			@Override
			public String next() {
				throw new NoSuchElementException();
			}

			@Override
			public void remove() {
				throw new UnsupportedOperationException();
			}

			@Override
			public void close() {
				closeCalls.incrementAndGet();
				sourceClosed.countDown();
			}
		};
		TimeLimitIteration<String> limited = new TimeLimitIteration<>(source, TimeUnit.DAYS.toMillis(1)) {
			@Override
			protected void throwInterruptedException() {
				throw new IllegalStateException("timed out");
			}
		};
		Thread timer = Thread.getAllStackTraces()
				.keySet()
				.stream()
				.filter(thread -> thread.isAlive() && thread.getName().equals("TimeLimitIteration scheduler"))
				.findFirst()
				.orElse(null);
		try {
			assertNotNull(timer, "the scheduled iteration must own a timer lease");
			limited.interrupt();
			assertTrue(sourceClosed.await(5, TimeUnit.SECONDS), "timeout cleanup must close the source");
			timer.join(TimeUnit.SECONDS.toMillis(1));
			assertFalse(timer.isAlive(), "a completed manual timeout must release its scheduler lease");
			assertEquals(1, closeCalls.get(), "the source is closed exactly once");
		} finally {
			limited.close();
		}
		assertEquals(1, closeCalls.get(), "a later explicit close must remain idempotent");
	}
}
